def _q(question, answer, follow_up, follow_up_answer):
    return dict(question=question, answer=answer, follow_up=follow_up,
                follow_up_answer=follow_up_answer)


def _entry(explanation, scenario, questions, mistake, drill, checks):
    return dict(explanation=explanation, scenario=scenario, questions=list(questions),
                mistake=mistake, drill=drill, checks=list(checks))


